def load(Disease):
    """Insert entries that do not exist yet (never overwrites reviewed content)."""
    from django.utils.text import slugify
    created = 0
    for d in DISEASES:
        _, new = Disease.objects.get_or_create(name=d["name"], defaults={**d, "slug": slugify(d["name"])})
        created += new
    return created
